import itertools, random, sys, importlib.util
spec = importlib.util.spec_from_file_location("main", "/workspace/submission/main.py")
main = importlib.util.module_from_spec(spec); spec.loader.exec_module(main)
rng=random.Random(int(sys.argv[1]) if len(sys.argv)>1 else 0)

def coreZ(rib):
    paths=main.aggregate(rib,set())
    links=set()
    for p in paths:
        for i in range(len(p)-1): links.add(main.canon(p[i],p[i+1]))
    rnd,cp=main.peel(paths)
    core=sorted(links-set(rnd))
    if not core: return None,None
    var_of={k:i for i,k in enumerate(core)}
    try: factors,_=main.build_factors(cp,var_of)
    except KeyError: return core,None
    return core, main.partition_value(factors,list(range(len(core))))

def cycle_paths(n, L):
    nodes=list(range(1,n+1))
    out=[]
    for s in range(n):
        for direction in (1,-1):
            p=[]
            cur=s
            for k in range(L):
                p.append(nodes[cur]); cur=(cur+direction)%n
            out.append(tuple(p))
    return out

# exhaustive over subsets of cycle paths for small cases
for n in (3,4,5,6):
    allp=[]
    for L in (2,3,4,5):
        if L<=n: allp.extend(cycle_paths(n,L))
    allp=list(dict.fromkeys(allp))
    print("n",n,"paths",len(allp))
    tries=0
    for it in range(300000):
        k=rng.randint(2,min(6,len(allp)))
        sub=rng.sample(allp,k)
        rib=[(list(p), rng.choice([1,1,2,3,5])) for p in sub]
        core,Z=coreZ(rib)
        if core is None or Z is None: continue
        tries+=1
        if Z==0:
            print("FOUND n",n,rib,core); sys.exit(0)
    print("  cores tested",tries,"no zero")
